mapper.select:
select a.parentId,a.parentName,ifnull(count(1),0) entrustCaseNum from ( select d.task_id parentId,d.task_name parentName,d.new_id,d.new_name,(case f.parent_id when 0 then f.id else f.parent_id end) as org_id from survey_case_direction d left join survey_assign_org o on d.survey_assorg_case_id = o.id left join survey_franchisee f on o.survey_org_id = f.id left join survey_risk_case_info r on d.survey_info_id = r.id left join survey_consignor n on r.entrust_org_id = n.id where d.delete_flag = 0 and r.delete_flag = 0 and o.delete_flag = 0
)a group by a.parentId,a.org_id
having a.org_id = #{surveyOrgId,jdbcType=BIGINT}

select
a.new_id as taskId,a.new_name as taskName,ifnull(count(1),0) entrustCaseNum
from (
  select d.task_id parentId,d.task_name parentName,d.new_id,d.new_name,(case f.parent_id when 0 then f.id else f.parent_id end) as org_id
  from survey_case_direction d
  left join survey_assign_org o on d.survey_assorg_case_id = o.id
  left join survey_franchisee f on o.survey_org_id = f.id
  left join survey_risk_case_info r on d.survey_info_id = r.id
  left join survey_consignor n on r.entrust_org_id = n.id
  where d.delete_flag = 0 and r.delete_flag = 0 and o.delete_flag = 0 and d.task_id = #{parentId,jdbcType=BIGINT}

)a
group by a.new_id,a.org_id

  having a.org_id = #{surveyOrgId,jdbcType=BIGINT}

select a.parentId,a.parentName,ifnull(count(1),0) entrustCaseNum from ( select d.task_id parentId,d.task_name parentName,d.new_id,d.new_name,c.survey_user_id from survey_case_direction d left join survey_investigator_case c on d.survey_investigator_case_id = c.id left join survey_risk_case_info r on d.survey_info_id = r.id left join survey_consignor n on r.entrust_org_id = n.id where d.delete_flag = 0 and r.delete_flag = 0 and c.delete_flag = 0
)a group by a.parentId,a.survey_user_id
having a.survey_user_id = #{surveyUserId,jdbcType=BIGINT}

select
a.new_id as taskId,a.new_name as taskName,ifnull(count(1),0) entrustCaseNum
from (
select d.task_id parentId,d.task_name parentName,d.new_id,d.new_name,c.survey_user_id
from survey_case_direction d
left join survey_investigator_case c on d.survey_investigator_case_id = c.id
left join survey_risk_case_info r on d.survey_info_id = r.id
left join survey_consignor n on r.entrust_org_id = n.id
where d.delete_flag = 0 and r.delete_flag = 0 and c.delete_flag = 0 and d.task_id = #{parentId,jdbcType=BIGINT}

)a
group by a.new_id,a.survey_user_id

  having a.survey_user_id = #{surveyUserId,jdbcType=BIGINT}
